  function getFeatureVisibilitySetting(featureKey) {
    const cfg = state.config || DEFAULT_CONFIG;
    if (cfg.featureVisibility && cfg.featureVisibility[featureKey]) {
      return cfg.featureVisibility[featureKey];
    }
    if (featureKey === 'id_cards') {
      return 'open';
    }
    if (featureKey === 'schedule' || featureKey === 'judges' || featureKey === 'judge_certs') {
      return 'disabled';
    }
    if (
      featureKey === 'venue' ||
      featureKey === 'substitution_form' ||
      featureKey === 'results' ||
      featureKey === 'certificates'
    ) {
      return 'hidden';
    }
    return 'auto';
  }

  function sanitizeCertRoleCode(raw, fallback) {
    const cleaned = String(raw === undefined || raw === null ? '' : raw)
      .replace(/[\s#?/&]+/g, '')
      .trim()
      .slice(0, 12);
    return cleaned || fallback;
  }

  function isScheduleModeDisabled() {
    return getFeatureVisibilitySetting('schedule') === 'disabled';
  }

  function isJudgesModeDisabled() {
    return getFeatureVisibilitySetting('judges') === 'disabled';
  }

  function isJudgeCertificatesEnabled() {
    return getFeatureVisibilitySetting('judge_certs') === 'open';
  }

  function isIdCardsPrintingEnabled() {
    return getFeatureVisibilitySetting('id_cards') === 'open';
  }

  function isSubstitutionFormEnabled() {
    return getFeatureVisibilitySetting('substitution_form') === 'open';
  }

  function isFeatureOpenToPublic(featureKey) {
    const setting = getFeatureVisibilitySetting(featureKey);
    if (setting === 'open') return true;
    if (setting === 'hidden' || setting === 'disabled') return false;
    const meta = FEATURE_MILESTONES[featureKey];
    if (!meta || !meta.openDateStr) return false;
    return Date.now() >= new Date(meta.openDateStr).getTime();
  }

  function isEffectiveAdmin() {
    return Boolean(state.isAdmin && !state.previewAsPublic);
  }

  function canUserAccessFeature(featureKey) {
    if (featureKey === 'schedule' && isScheduleModeDisabled()) {
      return false;
    }
    if (featureKey === 'judges' && isJudgesModeDisabled()) {
      return false;
    }
    if (isEffectiveAdmin()) return true;
    return isFeatureOpenToPublic(featureKey);
  }

  function shouldShowScoresInTables() {
    if (!ENABLE_PHASE_2) return false;
    if (isFeatureOpenToPublic('results')) return true;
    return Boolean(isEffectiveAdmin() && state.adminShowScoresInLists);
  }

  function getDistrictRepCriteriaLabel(criteria) {
    switch (criteria) {
      case 'rank_1_2':
        return 'อันดับ 1 และ อันดับ 2 (ชนะเลิศ และ รองชนะเลิศอันดับ 1)';
      case 'rank_1_3':
        return 'อันดับ 1 ถึง อันดับ 3 (ชนะเลิศ และ รองชนะเลิศอันดับ 1–2)';
      case 'gold_only':
        return 'เฉพาะทีมที่ได้เหรียญทอง อันดับ 1';
      case 'rank_1':
      default:
        return 'เฉพาะทีมชนะเลิศ (อันดับ 1)';
    }
  }

  function getDistrictRepCriteriaShortLabel(criteria) {
    switch (criteria) {
      case 'rank_1_2':
        return 'อันดับ 1–2';
      case 'rank_1_3':
        return 'อันดับ 1–3';
      case 'gold_only':
        return 'เหรียญทอง อันดับ 1';
      case 'rank_1':
      default:
        return 'อันดับ 1';
    }
  }

  function getDistrictRepLevelGroup(levelStr) {
    const lvl = String(levelStr || '').trim();
    if (!lvl) return 'primary';
    if (lvl.indexOf('ป.1–ม.3') !== -1 || lvl.indexOf('ป.1-ม.3') !== -1 || lvl.indexOf('ขยายโอกาส') !== -1) {
      return 'mixed';
    }
    if (lvl.indexOf('ม.') !== -1) {
      return 'secondary';
    }
    return 'primary';
  }

  function getDistrictRepCriteriaConfig(cfgInput) {
    const cfg = cfgInput || state.config || DEFAULT_CONFIG;
    return {
      primary: cfg.districtRepCriteriaPrimary || cfg.districtRepCriteria || 'rank_1',
      mixed: cfg.districtRepCriteriaMixed || 'rank_1',
      secondary: cfg.districtRepCriteriaSecondary || 'rank_1_2'
    };
  }

  function getDistrictRepCriteriaSummaryLabel(cfgInput) {
    const crit = getDistrictRepCriteriaConfig(cfgInput);
    return (
      'ประถมฯ: ' +
      getDistrictRepCriteriaShortLabel(crit.primary) +
      ' • ป.1–ม.3/ขยายโอกาส: ' +
      getDistrictRepCriteriaShortLabel(crit.mixed) +
      ' • มัธยมฯ (ม.1–ม.3): ' +
      getDistrictRepCriteriaShortLabel(crit.secondary)
    );
  }

  function isRegistrationAbsent(r) {
    if (!r) return false;
    const m = String(r.medal || '').trim();
    const a = String(r.award_title || '').trim();
    return (
      m === 'ไม่มาแข่งขัน' ||
      m === 'ขาดสอบ' ||
      a.indexOf('ไม่มาแข่งขัน') !== -1 ||
      a.indexOf('ขาดสอบ') !== -1
    );
  }

  function hasValidScore(r) {
    if (!r || isRegistrationAbsent(r)) return false;
    return r.score !== '' && r.score !== null && r.score !== undefined && !Number.isNaN(Number(r.score));
  }

  function isRegistrationByeRep(r) {
    if (!r) return false;
    const m = String(r.medal || '').trim();
    const a = String(r.award_title || '').trim();
    return m === 'ตัวแทนกลุ่ม (ไม่มีคู่แข่ง)' || a === 'ตัวแทนกลุ่ม (ไม่มีคู่แข่ง)';
  }

  function isRegistrationEvaluated(r) {
    if (!r) return false;
    return Boolean(hasValidScore(r) || isRegistrationAbsent(r) || isRegistrationByeRep(r));
  }

  function getCompetitionResultStats(comp, regsInput) {
    const compId = comp && comp.comp_id ? comp.comp_id : '';
    const regs = Array.isArray(regsInput)
      ? regsInput
      : compId
      ? state.registrations.filter((r) => r.comp_id === compId)
      : [];
    const total = regs.length;
    let evaluatedCount = 0;
    regs.forEach(function (r) {
      if (isRegistrationEvaluated(r)) evaluatedCount++;
    });
    const missingCount = Math.max(0, total - evaluatedCount);
    const hasAnyEvaluated = evaluatedCount > 0;
    const isComplete = total > 0 && missingCount === 0;
    const rawPublished = Boolean(comp && comp.result_status === 'ประกาศผลแล้ว');
    const isStalePublished = Boolean(rawPublished && !hasAnyEvaluated);
    const isAnnounced = Boolean(rawPublished && hasAnyEvaluated);
    return {
      total: total,
      evaluatedCount: evaluatedCount,
      missingCount: missingCount,
      hasAnyEvaluated: hasAnyEvaluated,
      isComplete: isComplete,
      isStalePublished: isStalePublished,
      isAnnounced: isAnnounced
    };
  }

  function isCompetitionResultAnnounced(comp, regsInput) {
    return getCompetitionResultStats(comp, regsInput).isAnnounced;
  }

  function getCompetitionTieStats(compId) {
    const regs = state.registrations.filter((r) => r.comp_id === compId && hasValidScore(r));
    const scoreCounts = {};
    const rankCounts = {};
    regs.forEach(function (r) {
      const key = Number(r.score).toFixed(2);
      scoreCounts[key] = (scoreCounts[key] || 0) + 1;
      const rk = Number(r.rank);
      if (rk > 0) rankCounts[rk] = (rankCounts[rk] || 0) + 1;
    });
    const tiedScores = Object.keys(scoreCounts).filter((k) => scoreCounts[k] > 1);
    const hasTie = tiedScores.length > 0;
    const hasUnresolvedTie = regs.some(function (r) {
      const key = Number(r.score).toFixed(2);
      if (scoreCounts[key] <= 1) return false;
      const rk = Number(r.rank);
      return !(rk > 0) || rankCounts[rk] > 1;
    });
    return { hasTie: hasTie, hasUnresolvedTie: hasUnresolvedTie, tiedScores: tiedScores };
  }

  function matchesDistrictRepCriteria(r, criteria) {
    const rank = Number(r.rank);
    const award = String(r.award_title || '').trim();
    const medal = String(r.medal || '').trim();

    if (criteria === 'rank_1_2') {
      return (rank >= 1 && rank <= 2) || award === 'ชนะเลิศ' || award === 'รองชนะเลิศอันดับ 1';
    }
    if (criteria === 'rank_1_3') {
      return (
        (rank >= 1 && rank <= 3) ||
        award === 'ชนะเลิศ' ||
        award === 'รองชนะเลิศอันดับ 1' ||
        award === 'รองชนะเลิศอันดับ 2'
      );
    }
    if (criteria === 'gold_only') {
      return (rank === 1 || award === 'ชนะเลิศ') && medal.includes('ทอง');
    }
    return rank === 1 || award === 'ชนะเลิศ';
  }

  function isDistrictRepresentative(r) {
    if (!r || isRegistrationAbsent(r) || !hasValidScore(r)) return false;
    let levelStr = r.level || '';
    if (!levelStr && r.comp_id) {
      const comp = state.competitions.find((c) => c.comp_id === r.comp_id);
      if (comp) levelStr = comp.level || '';
    }
    const group = getDistrictRepLevelGroup(levelStr);
    const critMap = getDistrictRepCriteriaConfig();
    const criteria = critMap[group] || 'rank_1';
    return matchesDistrictRepCriteria(r, criteria);
  }

